  {
    key = "rol", slug = "ruins-of-lordaeron", levels = "15-20",
    name = { ko = "로데론의 폐허", en = "Ruins of Lordaeron", de = "Ruinen von Lordaeron", fr = "Ruines de Lordaeron", es = "Ruinas de Lordaeron", ru = "Руины Лордерона", zhCN = "洛丹伦废墟", zhTW = "羅德隆廢墟" },
    instanceIDs = { 2999 }, nameMatch = { "로데론의 폐허", "Ruins of Lordaeron", "Ruinen von Lordaeron", "Ruines de Lordaeron", "Ruinas de Lordaeron", "Руины Лордерона", "洛丹伦废墟", "羅德隆廢墟" },
    entrance = { map = 1420, x = 63.3, y = 67.5, zone = { ko = "티리스팔 숲 로데론 폐허 안뜰 동쪽", en = "Eastern courtyard of the Lordaeron ruins, Tirisfal Glades" } },
    steps = {
      { id = "s1", n = "1", kind = "npc", npc = { 265701 }, optional = true, name = { ko = "트루먼 대위", en = "Captain Truman" }, quest = true, quests = { 95250 }, tip = { ko = "입구를 나와 바로 왼쪽(북쪽) 벽돌 길의 NPC. 얼라이언스 '흉측한 괴물들'을 주고받습니다(남작의 머리).", en = "Just left (north) of the entrance on the brick path. Alliance quest Abominable Creatures (the Baron's head)." } },
      { id = "s2", n = "2", kind = "boss", npc = { 250483 }, name = { ko = "쇠퇴송곳니", en = "Witherfang" }, quest = true, loot = { 271203, 271201, 271202 }, quests = { 95216 }, tip = { ko = "동쪽 거미 구역 넓은 방. 쫄 셋을 달고 긴 복도를 순찰하니, 자리를 비운 사이 남은 무리를 치우세요. 탱커에게 흡혈 독. 호드 '새로운 역병'의 균주.", en = "Big room in the east spider area. Patrols the hallway with three adds; clear while she's away. Leech Poison on the tank. Horde quest item." } },
      { id = "s3", n = "3", kind = "boss", npc = { 250660 }, name = { ko = "도살자(남작)", en = "The Butcher(The Baron)" }, quest = true, loot = { 271204, 271205, 271206 }, quests = { 95250, 97288 }, tip = { ko = "게임 안 이름은 '남작'. 거대한 누더기골렘이라 한 방이 아주 셉니다. 탱커 기절·띄우기·전방 베기. 부탱커를 정해 두고 딜러는 어그로 조절.", en = "Shown as The Baron in game. Huge abomination: Knockout stuns the tank, knock-up, cleave. Assign an off-tank; DPS watch threat." } },
      { id = "s7", n = "4", kind = "boss", npc = { 256035 }, optional = true, name = { ko = "비열한 빅토르", en = "Viktor the Vile" }, loot = { 271211, 271212, 271218 }, tip = { ko = "남작 다음 남쪽 길을 따라 서쪽 끝 둥근 탑 옆 벽난로로 갑니다. 불을 붙이면 적이 다섯 차례 몰려오고 여섯 번째에 빅토르가 나옵니다. 연속 공세와 강한 근접·흡혈 독에 대비해 체력과 마나를 채우세요. 공세 뒤 등장하지 않는 베타 오류가 보고됐습니다.", en = "After the Baron, follow the southern road west to the fireplace by the round tower. Light it: five waves, then Viktor as the sixth. Top up health/mana for continuous waves, hard melee and Leech Poison. A beta bug can prevent his appearance." } },
      { id = "s4", n = "5", kind = "boss", npc = { 250631 }, optional = true, name = { ko = "버려진 자", en = "The Abandoned" }, loot = { 271207, 271208, 271216 }, tip = { ko = "빅토르 벽난로 북동쪽 육각 지붕 건물의 통로를 지나 북쪽 문간으로 갑니다. 문간에 들어서면 세 차례 공세 뒤 네 번째에 나타납니다. 비선공 유령 시민은 건드리지 마세요. 얼음 회오리와 생명력 흡수(차단 가능).", en = "From the fireplace, pass through the hexagon-roofed building to the northeast and go north to the doorway. Three waves, then the Abandoned on the fourth. Leave non-aggressive Ghostly Citizens alone. Frost Nova and interruptible Life Drain." } },
      { id = "s5", n = "6", kind = "boss", npc = { 256097 }, name = { ko = "비요크", en = "Bjork" }, loot = { 271209, 271217, 271210 }, tip = { ko = "버려진 자 문간에서 계속 북쪽으로 가면 시장 거리 북서쪽 안개 구역입니다. 거대한 트롤 언데드가 순찰하니 해골·구울 무리를 먼저 정리하세요. 3초 대마법 보호막 동안 시전을 멈추고, 넉백에 대비해 벽을 등지세요.", en = "Continue north from the Abandoned doorway into foggy northwest Market Street. Clear skeletal mages and ghouls while avoiding the roaming undead troll. Hold spells during the 3-second Anti-Magic Shell; tank against a wall for knockback." } },
      { id = "s6", n = "7", kind = "boss", npc = { 250657 }, name = { ko = "라스마엘", en = "Rath'mael" }, quest = true, loot = { 271213, 271214, 271215, 273085, 273103 }, quests = { 92422 }, tip = { ko = "비요크 다음 남은 구울을 정리하며 연못 동쪽을 따라 남쪽 막다른 곳의 보라색 룬으로 갑니다. 마지막 우두머리를 룬 밖으로 끌어내세요. 불기둥은 차단 순서를 정하고 놓치면 즉시 피하세요.", en = "After Bjork, clear ghouls down the east side of the pools and go south to the purple rune in the dead end. Pull the final boss off the rune. Rotate interrupts for Flamestrike and dodge missed casts." } },
    },
    quests = {
      { id = 95250, faction = "Alliance", level = 21, minLevel = 16, name = { ko = "흉측한 괴물들", en = "Abominable Creatures" }, giver = { ko = "던전에서 남작의 머리(남작의 머리)를 가져와 대장 트루먼에게 전달", en = "Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman." } },
      { id = 92415, faction = "Alliance", level = 22, minLevel = 15, name = { ko = "내가 사랑한다는 걸 기억해", en = "Remember That I Love You" }, giver = { ko = "피로 얼룩진 편지를 스톰윈드에 있는 보육원 원장님 나이팅게일에게 가져가야 합니다.", en = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City." } },
      { id = 95189, faction = "Alliance", level = 22, minLevel = 16, name = { ko = "로데론의 문장", en = "Crest of Lordaeron" }, giver = { ko = "로데론의 문장을 스톰윈드에 있는 귀부인 디나 케네디에게 반환해야 합니다.", en = "Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City." } },
      { id = 95195, faction = "Alliance", level = 22, minLevel = 16, name = { ko = "피투성이 휘장", en = "Bloodied Insignia" }, giver = { ko = "드랍된 피투성이 휘장으로 시작해 10개를 모아 스톰윈드의 장군 마커스 조나단에게", en = "Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City." } },
