    notes = { { ko = "추천 순서: 트루먼 대위 → 쇠퇴송곳니 → 남작 → 비열한 빅토르(선택) → 버려진 자(선택) → 비요크 → 라스마엘.", en = "Suggested route: Captain Truman → Witherfang → the Baron → Viktor (optional) → the Abandoned (optional) → Bjork → Rath'mael." }, { ko = "쇠퇴송곳니가 쫄을 데리고 순찰합니다. 경로를 보고 시작하세요.", en = "Witherfang patrols with adds; watch her path." }, { ko = "'로데론의 문장'은 자리가 고정되지 않습니다. 건물 바닥을 살펴보세요.", en = "The Crest of Lordaeron has no fixed spot; check building floors." } },
