    entrance = { map = 1421, x = 69.6, y = 46.1, zone = { ko = "은빛소나무 숲 로다미어 호수 달라란 하수도 입구", en = "Dalaran sewer entrance by Lordamere Lake, Silverpine Forest" }, note = { ko = "하수도 문은 달라란 하수도 열쇠로 엽니다. 도시 안에서는 하수도의 선술집 옆 통로로 갈 수 있습니다.", en = "The outer sewer gate requires the Dalaran Sewer Key. From inside the city, use the passage beside the Underbelly tavern." } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 247126 }, name = { ko = "무덤 기사 아트렉시스", en = "Atrexis the Grave Knight" }, quest = true, loot = { 273036, 273032, 273033 }, quests = { 96986 }, tip = { ko = "하수도 지나 지하 의식의 원, 키린 토 강령술사들과 함께. 해골이 계속 일어나지만 약하니 나오는 대로 잡고, 탱커 무장 해제에 대비. 호드 퀘스트 '무덤 기사' 대상.", en = "Ritual Circle in the Underbelly with Kirin Tor Necromancers. Weak skeletons keep rising: kill them as they come. Disarms the tank. Horde quest The Grave Knight." } },
      { id = "s7", n = "2", kind = "boss", npc = { 247032 }, optional = true, name = { ko = "외면받는 린", en = "Lyn the Ignored" }, loot = { 273054, 273053, 273055 }, tip = { ko = "희귀 우두머리. 하수도 작은 원형 방의 의식진에서 달라란의 고서을 쓰면 나옵니다(만드는 법은 준비 탭).", en = "Rare boss: use the Tome of Dalaran on the ritual circle in the sewers' small round room (how to make it: Prep tab)." } },
      { id = "s2", n = "3", kind = "boss", npc = { 245999 }, name = { ko = "비전 변형물", en = "Arcane Anomaly" }, loot = { 273031, 273034, 273035 }, tip = { ko = "둥근 테라스의 거품에서 끌려 나옵니다. 3초 시전 뒤 정면으로 6초 광선(집중 폭발): 시전이 보이면 바로 앞에서 비키세요. 사이사이 탱커에게 비전 화살.", en = "Pulled from a bubble on the Round Terrace. After a 3s cast, Focal Blast beams straight ahead for 6s: get out of its front. Arcane Bolt on the tank in between." } },
      { id = "s3", n = "4", kind = "boss", npc = { 246003 }, name = { ko = "지옥의 고대정령", en = "Fel Ancient" }, loot = { 273039, 273038, 273037 }, tip = { ko = "도시 한가운데 룬위버 광장, 지옥 기운 스민 나무정령들 사이. 덩굴(지옥 목재)이 한 명에게 뻗어 주변 5미터를 치고 독 연기를 남기니 연기 밖으로 나가세요.", en = "Runeweaver Square in the city centre, among Suffused Treants. Fel Timbers hits everyone within 5 yd of one player and leaves poison fumes: move out." } },
      { id = "s5", n = "5", kind = "boss", npc = { 246008 }, name = { ko = "마나 포식자", en = "Mana Devourer" }, loot = { 273040, 273042, 273041 }, tip = { ko = "도시 남쪽 정원 근처, 분수 정원의 북쪽 끝(큰 주황 돔 위쪽). 기술 정보는 아직 없습니다.", en = "North end of the southern fountain garden (above the big orange dome). Abilities unknown yet." } },
      { id = "s6", n = "6", kind = "boss", npc = { 246016 }, name = { ko = "신비한 수수께끼", en = "Arcanic Enigma" }, aliases = { "Mana Elemental", "Arcanic Enigma", "마나 정령" }, quest = true, loot = { 273045, 273044, 273043 }, quests = { 92489 }, tip = { ko = "8초 변이(마법이라 해제 가능)와 10초 침묵이 있어 치유사는 떨어져 있으세요. 작은 마나 정령을 계속 불러내니 광역으로. 얼라이언스 '압도적인 힘' 대상.", en = "Named Arcanic Enigma. Manamorph (8s, magic: dispel) and a 10s silence: healers keep distance. Keeps calling Arcane Manalings: AoE them. Alliance quest Power Overwhelming." } },
      { id = "s4", n = "7", kind = "boss", npc = { 246017 }, name = { ko = "불안정한 파수꾼", en = "Unstable Sentinel" }, loot = { 273046, 273048, 273047, 273099 }, tip = { ko = "마법사 교역소. 가는 길에 달려드는 성난 고서를 먼저 잡으세요. 2초 시전 뒤 6초간 25미터 광역(오작동): 원거리는 25미터 밖, 근접은 시전 중에 빠지기.", en = "Magus Commerce Exchange; kill the Angry Tomes on the way first. After a 2s cast Malfunction pulses within 25 yd for 6s: ranged stay out, melee step out." } },
      { id = "s9", n = "8", kind = "boss", npc = { 246020 }, name = { ko = "대마법사의 망령", en = "Shade of the Archmage" }, loot = { 273052, 273051, 273049, 273103 }, tip = { ko = "도시 북서쪽 보랏빛 성채 앞 NPC와 대화해 위층 응접실로 이동합니다. 마나 구슬이 한 명에게 갔다 돌아오며 길목에 비전 피해와 6초 침묵: 우두머리와 그 사람 사이에 서지 마세요. 마나가 바닥나면 파티 전체 8초 변이 뒤 6초 환기. 전투 중 누가 방을 나가면 체력이 다 찹니다.", en = "Talk to the NPC in front of the Violet Citadel in the northwest of the city to be teleported to the Purple Parlor. Bounding Mana flies to a player and back, silencing anyone in its path: don't stand between them. Out of mana he polymorphs the group (8s), then Evocation (6s). Leaving the room resets him." } },
    },
    quests = {
      { id = 92456, rewards = { { id = 279835, name = { ko = "덩굴치기의 망토", en = "Vine Pruner's Cloak" } }, { id = 279836, name = { ko = "가시막이 요대", en = "Thorn Protecting Girdle" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "녹색 표본", en = "A Green Sample" }, giver = { ko = "달라란에서 지옥 마력이 주입된 꽃을 구해 스톰윈드에 있는 샤이라미르에게 가져가야 합니다.", en = "Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City." } },
      { id = 92458, rewards = { { id = 279839, name = { ko = "주문수호 견갑", en = "Spellguard Pauldrons" } }, { id = 279840, name = { ko = "소생의 발보호구", en = "Renewing Footpads" } }, { id = 279841, name = { ko = "달라란의 수호자", en = "Defender of Dalaran" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "분열의 심장", en = "Heart of Disruption" }, giver = { ko = "달라란 근처의 대마법사 모데라의 환영를 위해 달라란에서 비전 티끌를 구해야 합니다. 이 퀘스트를 받으면 달라란 하수도 열쇠를 줍니다.", en = "Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran. Taking it gives you the Dalaran Sewer Key." } },
      { id = 92489, rewards = { { id = 251962, name = { ko = "보랏빛 장식띠", en = "Violet Sash" } }, { id = 279849, name = { ko = "룬결속 장갑", en = "Runebound Gloves" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "압도적인 힘", en = "Power Overwhelming" }, giver = { ko = "스톰윈드에 있는 고위마술사 안드로매스를 위해 달라란에서 마나 정령을 처치해야 합니다.", en = "Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City." } },
      { id = 96984, rewards = { { id = 279842, name = { ko = "전투 어깨덮개", en = "Battle Spaulders" } }, { id = 279843, name = { ko = "마력 깃든 덧신", en = "Enchanted Sandals" } }, { id = 279844, name = { ko = "강타의 지팡이", en = "Striking Staff" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "분열의 심장", en = "Heart of Disruption" }, giver = { ko = "타렌 밀농장에 있는 마법학자 워딘 보이드글레어를 위해 달라란에서 비전 티끌를 구해야 합니다. 이 퀘스트를 받으면 달라란 하수도 열쇠를 줍니다.", en = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill. Taking it gives you the Dalaran Sewer Key." } },
      { id = 96987, rewards = { { id = 279845, name = { ko = "순금 고리", en = "Solid Gold Band" } }, { id = 279846, name = { ko = "절도범의 허리띠", en = "Larcenist's Belt" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "기회주의 학습법", en = "Opportunistic Education" }, giver = { ko = "하수도 입구 근처에 있는 렉시 코퍼클러치를 위해 달라란에서 달라란 건국사를 구해야 합니다.", en = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance." } },
      { id = 96986, rewards = { { id = 251963, name = { ko = "무덤걸이 장화", en = "Gravewalker Boots" } }, { id = 251965, name = { ko = "언데드 기사의 팔보호구", en = "Undead Knight's Bracers" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "무덤 기사", en = "The Grave Knight" }, giver = { ko = "타렌 밀농장에 있는 멜리사라를 위해 달라란에서 무덤 기사 아트렉시스를 쓰러뜨려야 합니다.", en = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill." } },
      { id = 96988, rewards = { { id = 279847, name = { ko = "불안정한 동력 핵", en = "Unstable Power Core" } }, { id = 279848, name = { ko = "피조물 망토", en = "Construct Cloak" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "힘의 원천", en = "Source of Power" }, giver = { ko = "언더시티에 있는 박사 마틴 펠벤을 위해 달라란에서 금이 간 파수꾼 핵 6개를 모아야 합니다.", en = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity." } },
      { id = 92457, rewards = { { id = 279837, name = { ko = "쓰러진 경비병의 펜던트", en = "Fallen Guard's Pendant" } }, { id = 279838, name = { ko = "비전 마력이 주입된 마법막대", en = "Arcane Infused Rod" } } }, level = 33, minLevel = 24, name = { ko = "굶주린 비전", en = "Starving Arcane" }, giver = { ko = "달라란 밖에 있는 대마법사 모데라를 위해 달라란 안에서 갈구하는 잔재 8마리, 충만한 잔재 8마리, 마나 메아리 8마리를 처치해야 합니다.", en = "Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran." } },
    },
    trash = { 273043 },
    trashGroups = {
      { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 273043 } },
    },
    notes = { { ko = "호드 주의: 10월 15일 패치부터 하수도 열쇠를 얻어도 야외 달라란 도시에서는 공격받습니다. 도시 자유 출입 권한은 없어졌지만 하수도를 통한 달라란 던전 입장은 가능합니다.", en = "Horde warning: since the October 15 update, the sewer key no longer grants safe access to outdoor Dalaran; city NPCs attack Horde on sight. Dungeon access through the sewers is unchanged." }, { ko = "권장 28~33레벨이고 던전 퀘스트는 24레벨부터 받습니다.", en = "Levels 28-33; dungeon quests from level 24." }, { ko = "입구는 하수도를 지나 긴 관 끝의 차원문. 하수도 문은 입장 퀘스트로 받는 달라란 하수도 열쇠로 열고, 입장 퀘스트를 마친 사람이 파티에 한 명 있으면 모두 들어갑니다.", en = "Entrance: the portal at the end of a long pipe through the sewers. The sewer door needs the Dalaran Sewer Key from the attunement; one attuned member lets the whole group in." }, { ko = "얼라이언스 입장: 힐스브래드 사절 자크 '불길한 요청'(30레벨~) → 은빛소나무 숲 동쪽 끝 대마법사 모데라의 환영 '분열의 심장'(열쇠) → 보랏빛 성채 대마법사 셀린드라 '키린 토의 친구'.", en = "Alliance attunement: An Alarming Request (Emissary Jacques, Hillsbrad, from 30) → Heart of Disruption (Image of Archmage Modera, east Silverpine; gives the key) → Friend of the Kirin Tor (Archmage Celindra)." }, { ko = "호드 입장: 타렌 밀농장 마법학자 워딘 보이드글레어의 다른 퀘스트를 끝낸 뒤 '거리에 흐르는 피'(30레벨~) → '분열의 심장' → 대마법사 셀린드라 '빈틈없는 협상'.", en = "Horde attunement: finish Magus Wordeen Voidglare's other quests in Tarren Mill, then Blood in the Streets (from 30) → Heart of Disruption → Shrewd Negotiations (Archmage Celindra)." }, { ko = "희귀 외면받는 린: 그림자송곳니 성채 아루갈 뒤의 검은 고서을 은빛소나무 숲 앰버밀(63.4, 64.3)의 수정에 쓰면 달라란의 고서이 됩니다.", en = "Rare Lyn the Ignored: use the Black Tome (behind Arugal, Shadowfang Keep) on the crystal at Ambermill, Silverpine (63.4, 64.3) to make the Tome of Dalaran." }, { ko = "하수도에서 시작해 도시로 올라갑니다. 하수도와 도시를 별도 미니맵으로 표시하며, 연결 표식을 누르면 다른 구역으로 전환합니다. 보스 표식은 공략 자료를 참고한 위치입니다.", en = "The run starts in the sewers and climbs to the city. The floors have separate native minimaps and reciprocal clickable guide links. Boss markers are registered guide reference positions." } },
  },
  {
    key = "gnomer", slug = "gnomeregan", levels = "29-38",
    name = { ko = "놈리건", en = "Gnomeregan", de = "Gnomeregan", fr = "Gnomeregan", es = "Gnomeregan", ru = "Гномреган", zhCN = "诺莫瑞根", zhTW = "諾姆瑞根" },
    instanceIDs = { 90 }, nameMatch = { "놈리건", "Gnomeregan", "Гномреган", "诺莫瑞根", "諾姆瑞根" },
    entrance = { map = 1426, x = 17.7, y = 39.2, zone = { ko = "던 모로 서쪽 놈리건 정문", en = "The front gate of Gnomeregan in western Dun Morogh" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 7361 }, model = 6533, name = { ko = "그루비스", en = "Grubbis" }, loot = { 9445, 274042, 274043 }, tip = { ko = "폭발물전문가 에미에게 말을 걸면 에미가 입구를 폭파하는 동안 트로그가 몰려오고 끝에 그루비스가 나옵니다. 에미를 지키세요.", en = "Talk to Blastmaster Emi: troggs rush in while she seals the tunnels, then Grubbis comes. Keep Emi alive." } },
      { id = "s2", n = "2", kind = "boss", npc = { 7079 }, model = 5497, name = { ko = "방사성 폐기물", en = "Viscous Fallout" }, quest = true, loot = { 9454, 9453, 9452 }, quests = { 2962 }, tip = { ko = "방사능 구역의 우두머리. 근처 방사능 몹에게서 얼라이언스 '유일한 치료법'의 폐기물을 얻습니다.", en = "Boss of the irradiated zone. Mobs here give the fallout for the Alliance quest The Only Cure is More Green Glow." } },
      { id = "s3", n = "3", kind = "npc", name = { ko = "케르노비", en = "Kernobee" }, quest = true, quests = { 2904 }, tip = { ko = "케르노비를 찾아 태엽장치 통로 출구까지 호위하세요('곤경에 빠진 케르노비'). 서 있는 자리는 여러 곳 중 하나.", en = "Find Kernobee and escort him to the Clockwerk Run exit (A Fine Mess). He stands at one of several spots." } },
      { id = "s4", n = "4", kind = "object", optional = true, name = { ko = "삐까뻔쩍세척기 5200", en = "The Sparklematic 5200" }, quest = true, quests = { 2930, 2945, 2951 }, tip = { ko = "정화 지역의 세척기. 꼬질꼬질한 반지를 넣어 닦습니다. 근처에 천공기록기 3005-B.", en = "Sparklematic in the Clean Zone: clean the Grime-Encrusted Ring here. Punchograph 3005-B is nearby." } },
      { id = "s5", n = "5", kind = "boss", npc = { 6235 }, model = 6915, name = { ko = "기계화 문지기 6000", en = "Electrocutioner 6000" }, quest = true, loot = { 9447, 9446, 9448, 6893 }, quests = { 2930 }, tip = { ko = "전격·연쇄 벼락·100만 볼트. 흩어져 서세요. 작업장 열쇠를 떨구고, 방에 천공기록기 3005-C.", en = "Shock, Chain Bolt, Megavolt. Spread out. Drops the Workshop Key; Punchograph 3005-C in his room." } },
      { id = "s6", n = "6", kind = "boss", npc = { 6229 }, model = 6774, name = { ko = "고철 압축기 9-60", en = "Crowd Pummeler 9-60" }, quest = true, loot = { 9449, 9450, 274049, 274068 }, quests = { 2930 }, tip = { ko = "회전 강타·밟아 뭉개기·고철 압축으로 주변을 칩니다. 근접은 옆·뒤, 원거리는 멀리. 출격실에 3005-D.", en = "Arcing Smash, Trample, Crowd Pummel hit all around. Melee at sides/back, ranged far. Punchograph 3005-D in the bay." } },
      { id = "s7", n = "7", kind = "rare", optional = true, npc = { 6228 }, model = 6669, name = { ko = "검은무쇠단 사절", en = "Dark Iron Ambassador" }, loot = { 9455, 9456, 9457 }, tip = { ko = "희귀 몹. 화염구, 화염 보호막·냉기 갑옷, 불타는 하수인 소환. 지나가도 됩니다.", en = "Rare: Fireball, Fire Shield, Frost Armor, summons a servant. Skippable." } },
      { id = "s8", n = "8", kind = "npc", optional = true, name = { ko = "검은무쇠단 첩보원", en = "Dark Iron Agent" }, quest = true, quests = { 2945 }, tip = { ko = "첩보원이 떨구는 꼬질꼬질한 반지로 같은 이름의 퀘스트가 시작됩니다. 여러 곳에 나옵니다.", en = "Agents drop the Grime-Encrusted Ring that starts its quest. Found in many places." } },
      { id = "s9", n = "9", kind = "boss", npc = { 7800 }, model = 6980, name = { ko = "멕기니어 텔마플러그", en = "Mekgineer Thermaplugg" }, quest = true, loot = { 9461, 9458, 4415, 4413, 4411, 7742, 9492, 9459, 6672, 7192, 7560, 7561 }, quests = { 2841, 2929 }, tip = { ko = "날려버리기로 탱커를 밀칩니다. 방 둘레 놈 얼굴 장치에서 폭탄 로봇이 나오니 장치를 누르거나 로봇을 먼저 처리.", en = "Knock Away on the tank. Bombs walk out of the gnome-face machines; press them or kill bombs first." } },
      { id = "s10", n = "10", kind = "object", optional = true, name = { ko = "텔마플러그의 금고", en = "Thermaplugg's Safe" }, quest = true, quests = { 2841 }, tip = { ko = "호드 '기술 전쟁'의 설계도가 든 금고. 비밀번호는 텔마플러그가 떨굽니다.", en = "Safe with the blueprints for the Horde quest Rig Wars; Thermaplugg drops the code." } },
    },
    quests = {
      { id = 2962, faction = "Alliance", level = 30, minLevel = 20, name = { ko = "유일한 치료법", en = "The Only Cure is More Green Glow" }, giver = { ko = "놈리건으로 가서 고농축 방사성 폐기물을 가져와야 합니다. 이 폐기물은 불안정하여 성분이 금방 변할 수 있으니 주의하십시오. 임무를 완수한 후 빈 대형 가연채집병을 오지에게 돌려줘야 합니다.", en = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly. Ozzie will also require your Heavy Leaden Collection Phial when the task is complete." } },
      { id = 2930, faction = "Alliance", level = 30, minLevel = 25, name = { ko = "자료 회수", en = "Data Rescue" }, giver = { ko = "아이언포지에 있는 수석수리공 캐스트파이프에게 오색 천공 카드를 가져가야 합니다.", en = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge." } },
      { id = 2924, faction = "Alliance", level = 30, minLevel = 24, name = { ko = "필수 인공장치", en = "Essential Artificials" }, giver = { ko = "아이언포지에 있는 클락몰트 스패너스판에게 필수 인공장치 12개를 가져가야 합니다.", en = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge." } },
      { id = 2928, faction = "Alliance", level = 30, minLevel = 20, name = { ko = "회전천공식 발굴기", en = "Gyrodrillmatic Excavationators" }, giver = { ko = "스톰윈드에 있는 쇼니에게 기계장치 부속품 24개를 가져가야 합니다.", en = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind." } },
      { id = 2929, faction = "Alliance", level = 35, minLevel = 25, name = { ko = "대배반", en = "The Grand Betrayal" }, giver = { ko = "놈리건으로 가서 멕기니어 텔마플러그를 처치해야 합니다. 임무가 끝나면 땜장이왕 멕카토크에게 돌아와야 합니다.", en = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete." } },
      { id = 95041, minLevel = 7, faction = "Alliance", name = { ko = "자료 수집광", en = "Data Hoarders" }, giver = { ko = "놈리건 전역의 놈리건 보관 자료 카드 7장을 수집한 후, 아이언포지에 있는 젬마 퀵스위치에게 전달해야 합니다.", en = "Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge." } },
      { id = 2841, faction = "Horde", level = 35, minLevel = 25, name = { ko = "기술 전쟁", en = "Rig Wars" }, giver = { ko = "놈리건에서 장치 설계도와 텔마플러그의 금고 암호를 찾아서 오그리마에 있는 노그에게 가져다주어야 합니다.", en = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar." } },
      { id = 2904, level = 30, minLevel = 24, name = { ko = "곤경에 빠진 케르노비", en = "A Fine Mess" }, giver = { ko = "태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.", en = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay." } },
      { id = 2951, level = 30, minLevel = 25, name = { ko = "삐까뻔쩍세척기 5200!", en = "The Sparklematic 5200!" }, giver = { ko = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 3실버를 투입하면 작동할 것입니다.", en = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine." } },
      { id = 2945, level = 34, minLevel = 28, name = { ko = "꼬질꼬질한 반지", en = "Grime-Encrusted Ring" }, giver = { ko = "꼬질꼬질한 반지에서 찌꺼기를 제거할 방법을 찾아야 합니다.", en = "Figure out a way to remove the grime from the Grime-Encrusted Ring." } },
    },
