      { id = "s5", n = "5", kind = "rare", optional = true, name = { ko = "가시덩굴일족 가시근위병", en = "Razorfen Spearhide" }, loot = { 6679 }, tip = { ko = "램터스크 곁의 정예. 가시 오라와 소용돌이 탄막.", en = "Elite beside Ramtusk: Thorns Aura, Whirling Barrage." } },
      { id = "s6", n = "6", kind = "rare", optional = true, npc = { 4842 }, model = 6102, name = { ko = "대지의주술사 함가르", en = "Earthcaller Halmgar" }, loot = { 6688, 6689 }, tip = { ko = "희귀 몹. 바위 정령 소환, 속박의 토템, 번개 화살. 지나가도 됩니다.", en = "Rare: Earth Rumbler, Earthbind Totem, Lightning Bolt. Skippable." } },
      { id = "s7", n = "7", kind = "boss", npc = { 4422 }, model = 2450, name = { ko = "흉포한 아가테로스", en = "Agathelos the Raging" }, loot = { 6691, 6690, 274160 }, tip = { ko = "맹렬한 돌진, 분노·격노. 탱커가 단단히 잡아 두세요.", en = "Rushing Charge, Enrage, Rampage. Tank must hold him firmly." } },
      { id = "s8", n = "8", kind = "rare", optional = true, npc = { 4425 }, model = 4735, name = { ko = "눈먼사냥꾼", en = "Blind Hunter" }, quest = true, loot = { 6695, 6697, 6696 }, quests = { 1109 }, tip = { ko = "박쥐 동굴의 희귀 몹. 이 박쥐들이 호드 '조분석을 나에게!'의 조분석을 떨굽니다.", en = "Rare in the bat cave; the bats drop guano for the Horde quest." } },
      { id = "s9", n = "9", kind = "npc", name = { ko = "수입업자 윌릭스", en = "Willix the Importer" }, quest = true, quests = { 1142, 1144, 1221 }, tip = { ko = "갇혀 있는 윌릭스. 입구까지 호위하면 퀘스트 완료. 청엽수 줄기 자리도 이 근처에 많습니다.", en = "Willix is held here; escort him to the entrance. Many Blueleaf Tuber spots nearby." } },
      { id = "s10", n = "10", kind = "npc", name = { ko = "헤랄라스 팰로우브룩", en = "Heralath Fallowbrook" }, quest = true, quests = { 1142 }, tip = { ko = "헤랄라스의 주검. 얼라이언스 '꺼져가는 생명의 불씨'를 받습니다.", en = "Heralath's body gives the Alliance quest Mortality Wanes." } },
      { id = "s11", n = "11", kind = "boss", npc = { 4421 }, model = 4642, name = { ko = "서슬깃 차를가", en = "Charlga Razorflank" }, quest = true, loot = { 6692, 6693, 6694, 17008 }, quests = { 1101, 1102 }, tip = { ko = "연쇄 벼락·마나 쐐기, 소생으로 회복. 흩어져 서고 소생을 해제하세요. 퀘스트용 메달·심장을 떨굽니다.", en = "Chain Bolt, Mana Spike, heals with Renew. Spread out and dispel Renew. Drops quest medallion/heart." } },
