    quests = {
      { id = 1701, faction = "Alliance", level = 28, minLevel = 20, name = { ko = "불에 달궈 만든 갑옷", en = "Fire Hardened Mail" }, giver = { ko = "스톰윈드에 있는 푸렌 롱비어드에게 그가 필요로 하는 재료들을 모아서 가져가야 합니다.", en = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind." } },
      { id = 1142, faction = "Alliance", level = 30, minLevel = 25, name = { ko = "꺼져가는 생명의 불씨", en = "Mortality Wanes" }, giver = { ko = "트레샬라의 펜던트를 찾아 다르나서스에 있는 트레샬라 팰로우브룩에게 돌려주어야 합니다.", en = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus." } },
      { id = 1101, faction = "Alliance", level = 34, minLevel = 29, name = { ko = "가시덩굴 우리의 대모", en = "The Crone of the Kraul" }, giver = { ko = "탈라나르에 있는 팔핀델 웨이워더에게 차를가의 메달을 가져가야 합니다.", en = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar." } },
      { id = 1838, faction = "Horde", level = 30, minLevel = 20, name = { ko = "투사의 방어구", en = "Brutal Armor" }, giver = { ko = "툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.", en = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston." } },
      { id = 1109, faction = "Horde", level = 33, minLevel = 30, name = { ko = "조분석을 나에게!", en = "Going, Going, Guano!" }, giver = { ko = "언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다.", en = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity." } },
      { id = 1102, faction = "Horde", level = 34, minLevel = 29, name = { ko = "운명의 복수", en = "A Vengeful Fate" }, giver = { ko = "썬더 블러프에 있는 아울드 스톤스파이어에게 차를가의 심장을 가져가야 합니다.", en = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff." } },
      { id = 1221, level = 26, minLevel = 20, name = { ko = "청엽수 줄기", en = "Blueleaf Tubers" }, giver = { ko = "구멍 난 상자를 집어야 합니다. 땅다람쥐 지휘봉도 챙겨야 합니다. 땅다람쥐 설명서를 찾아서 읽어야 합니다. 가시덩굴 우리에서 구멍 난 상자를 사용해 땅다람쥐를 소환하고 지휘봉을 사용해 땅다람쥐에게 청엽수 줄기를 찾아내도록 해야 합니다. 톱니항에 있는 메보크 미지릭스에게 청엽수 줄기 6개와 사용한 땅다람쥐 지휘봉과 구멍 난 상자를 가져가야 합니다.", en = "Grab a Crate with Holes. Grab a Snufflenose Command Stick. Grab and read the Snufflenose Owner's Manual. In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers. Bring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet." } },
      { id = 1144, level = 30, minLevel = 23, name = { ko = "수입업자 윌릭스", en = "Willix the Importer" }, giver = { ko = "수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다.", en = "Escort Willix the Importer out of Razorfen Kraul." } },
