    instanceIDs = { 230 }, nameMatch = { "검은바위 나락", "Blackrock Depths", "Глубины Черной горы", "黑石深渊", "黑石深淵" },
    entrance = { map = 1428, x = 29.0, y = 38.0, zone = { ko = "검은바위 산 안쪽 아래(불타는 평원 북서쪽에서 입장)", en = "Deep inside Blackrock Mountain (enter from northwest Burning Steppes)" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 9018 }, name = { ko = "대심문관 게르스탄", en = "High Interrogator Gerstahn" }, loot = { 11624, 11625, 11626, 22240, 11140 }, tip = { ko = "감금 구역 남쪽 방. 마나 연소를 끊고 공포에 대비하세요. 감방 열쇠를 떨굽니다.", en = "South room of the Detention Block. Interrupt Mana Burn, prepare for fear. Drops the cell key." } },
      { id = "s2", n = "", kind = "npc", quest = true, optional = true, npc = { 9023 }, name = { ko = "치안대장 윈저", en = "Marshal Windsor" }, quests = { 4322 }, tip = { ko = "감방에 갇혀 있습니다. 풀어 주면 긴 호위가 시작됩니다(얼라이언스 탈옥!).", en = "Locked in a cell; freeing him starts a long escort (Alliance Jail Break!)." } },
      { id = "s3", n = "", kind = "npc", quest = true, optional = true, npc = { 9020 }, name = { ko = "사령관 고르샤크", en = "Commander Gor'shak" }, quests = { 3981, 3982 }, tip = { ko = "감방에 갇혀 있습니다. 풀어 주면 몰려오는 드워프를 막아야 합니다(호드).", en = "Locked in a cell; free him and hold off the dwarves (Horde)." } },
      { id = "s4", n = "2", kind = "boss", npc = { 9025 }, name = { ko = "불의 군주 록코르", en = "Lord Roccor" }, loot = { 11632, 11631, 22234, 22397, 11630 }, tip = { ko = "법의 심판장 북쪽 둘레를 돕니다. 지진이 시전을 끊으니 원거리는 멀리.", en = "Patrols north of the Ring of Law; his earthquake interrupts, ranged stay far." } },
      { id = "s5", n = "3", kind = "boss", npc = { 9319 }, name = { ko = "사냥개조련사 그렙마르", en = "Houndmaster Grebmar" }, loot = { 11627, 11623, 11628, 11629 }, tip = { ko = "통로 가장 낮은 곳. 사냥개부터 잡으세요.", en = "Lowest part of the passage; kill the hounds first." } },
      { id = "s6", n = "4", kind = "boss", npc = { 9027, 9028, 9029, 9030, 9031, 9032 }, name = { ko = "법의 심판장", en = "Ring of Law" }, loot = { 22271, 22257, 22266, 11726, 11610, 11722, 11703, 11702 }, tip = { ko = "투기장 가운데로 가면 문이 닫히고 짐승 두 무리 뒤에 투사 하나가 무작위로 나옵니다. 이기면 동쪽 문이 열립니다.", en = "Step into the arena: the gates close, two beast waves, then a random champion. Winning opens the east gate." } },
      { id = "s7", n = "5", kind = "boss", quest = true, npc = { 9017 }, name = { ko = "불의 군주 인센디우스", en = "Lord Incendius" }, loot = { 11764, 11765, 11766, 11767, 19268, 11768 }, quests = { 4263, 3907 }, tip = { ko = "검은 모루. 벽을 등지고, 저주는 쌓이기 전에 해제. 원거리는 흩어져 서세요.", en = "At the Black Anvil; back to a wall, dispel the curse early, ranged spread out." } },
      { id = "s8", n = "6", kind = "boss", quest = true, npc = { 9056 }, name = { ko = "파이너스 다크바이어", en = "Fineous Darkvire" }, loot = { 11841, 11842, 11839, 22223, 11840 }, quests = { 3802 }, tip = { ko = "장인의 전당 비탈을 돕니다. 성스러운 빛을 반드시 끊으세요. 무쇠지옥(아이언펠)을 줍니다.", en = "Walks the slope of the Hall of Crafting; always interrupt Holy Light. Drops Ironfel." } },
      { id = "s9", n = "7", kind = "boss", npc = { 9024 }, name = { ko = "화염술사 로어그레인", en = "Pyromancer Loregrain" }, loot = { 11747, 11748, 11749, 11750 }, tip = { ko = "석상 앞에 무릎 꿇고 있습니다. 토템을 바로 부수세요.", en = "Kneels before the statue; smash his totems at once." } },
      { id = "s10", n = "8", kind = "object", quest = true, npc = {  }, name = { ko = "프랑클론 포지라이트의 석상", en = "Statue of Franclorn Forgewright" }, quests = { 3802 }, tip = { ko = "무쇠지옥을 올리면 그림자 제련 열쇠를 받습니다(지름길 문).", en = "Place Ironfel here for the Shadowforge Key (shortcut doors)." } },
      { id = "s11", n = "", kind = "boss", optional = true, npc = { 9041, 9042 }, name = { ko = "문지기 스틸기스와 베레크", en = "Warder Stilgiss and Verek" }, loot = { 11782, 11783, 11784, 22241, 11755, 22242 }, tip = { ko = "검은 금고. 스틸기스부터 잡고, 냉기 주문은 쓰지 마세요.", en = "The Black Vault; kill Stilgiss first and avoid frost spells." } },
      { id = "s12", n = "", kind = "task", quest = true, optional = true, npc = {  }, name = { ko = "검은 금고", en = "The Black Vault" }, quests = { 4123 }, tip = { ko = "유물 금고 12개를 열쇠로 열면 둠그립과 골렘이 깨어납니다. 잡으면 산의 정수를 꺼냅니다.", en = "Open all 12 relic coffers; Doomgrip and golems wake. Then take the Heart of the Mountain." } },
      { id = "s13", n = "", kind = "boss", quest = true, optional = true, npc = { 9016 }, name = { ko = "밸가르", en = "Bael'Gar" }, loot = { 11802, 11803, 11805, 11807 }, quests = { 4024 }, tip = { ko = "대로 서쪽 끝. 용암을 피해 모두 뒤에 서고, 용암 덩어리를 먼저 잡으세요.", en = "West end of the highway; stand behind him away from lava, kill the lava adds first." } },
      { id = "s14", n = "9", kind = "boss", quest = true, npc = { 9033 }, name = { ko = "사령관 앵거포지", en = "General Angerforge" }, loot = { 11816, 11820, 11821, 11817, 11810 }, quests = { 4132, 4282 }, tip = { ko = "비탈 위에서 원거리로 끌어오세요. 체력이 낮으면 지원군을 부르니 빨리 마무리.", en = "Pull him from the slope with a ranged attack. Calls reinforcements when low; finish fast." } },
      { id = "s15", n = "10", kind = "boss", quest = true, npc = { 8983 }, name = { ko = "골렘 군주 아젤마크", en = "Golem Lord Argelmach" }, loot = { 11822, 11823, 11669, 11819 }, quests = { 4063, 4282 }, tip = { ko = "함께 깨어나는 골렘부터. 번개 보호막 때문에 근접은 조심, 연쇄 번개를 끊으세요.", en = "Golems first. His lightning shield hurts melee; interrupt Chain Lightning." } },
      { id = "s16", n = "", kind = "boss", quest = true, optional = true, npc = { 9537 }, name = { ko = "헐레이 블랙브레스", en = "Hurley Blackbreath" }, loot = { 18044, 18043, 22275, 11735 }, quests = { 4126, 4134 }, tip = { ko = "선술집 안쪽 맥주통 셋을 깨면 친구들과 나옵니다. 손님이 맞지 않게 구석에서.", en = "Break the three casks in the tavern; he comes with friends. Fight in a corner away from patrons." } },
      { id = "s17", n = "", kind = "boss", quest = true, optional = true, npc = { 9543 }, name = { ko = "리블리 스크류스피곳", en = "Ribbly Screwspigot" }, loot = { 2662, 2663, 11742 }, quests = { 4136 }, tip = { ko = "평소 우호적. 대화로 위협하면 패거리와 덤빕니다.", en = "Friendly until you threaten him in dialogue; then he and his gang attack." } },
      { id = "s18", n = "11", kind = "npc", npc = { 9503 }, name = { ko = "병사 락노트", en = "Private Rocknot" }, tip = { ko = "검은무쇠 에일을 몇 번 주면 팔란스가 깨어나 문을 부숩니다(마법의 방 가는 길).", en = "Give him Dark Iron Ale a few times; Phalanx wakes and breaks the door." } },
      { id = "s19", n = "12", kind = "boss", npc = { 9502 }, name = { ko = "팔란스", en = "Phalanx" }, loot = { 11745, 11744, 22212, 11743 }, tip = { ko = "문 근처. 강한 일격과 천둥벼락, 연발 화염구에 대비하세요.", en = "Near the door; brace for heavy hits, Thunderclap and Fireball Volley." } },
      { id = "s20", n = "", kind = "boss", optional = true, npc = { 9499 }, name = { ko = "플러거 스파즈링", en = "Plugger Spazzring" }, loot = { 12793, 12791, 11602 }, tip = { ko = "술집 주인. 건드리면 술집 전체가 적대합니다.", en = "The barkeep; attacking him turns the tavern hostile." } },
      { id = "s21", n = "", kind = "npc", quest = true, optional = true, npc = { 9500 }, name = { ko = "지배인 나그마라", en = "Mistress Nagmara" }, quests = { 4201 }, tip = { ko = "선술집 2층. 사랑의 묘약 퀘스트.", en = "Tavern upstairs; The Love Potion." } },
      { id = "s22", n = "", kind = "npc", optional = true, npc = { 12944 }, name = { ko = "로크토스 다크바게이너", en = "Lokhtos Darkbargainer" }, tip = { ko = "토륨 대장조합 상인.", en = "Thorium Brotherhood vendor." } },
      { id = "s23", n = "13", kind = "boss", npc = { 9156 }, name = { ko = "사자 화염채찍", en = "Ambassador Flamelash" }, loot = { 11812, 11814, 11809, 11832, 11808 }, tip = { ko = "둘레 룬에서 나오는 불타는 정령이 닿으면 강해지니 원거리가 미리 잡으세요.", en = "Burning spirits from the runes empower him; ranged kill them before they arrive." } },
      { id = "s24", n = "14", kind = "boss", npc = { 9034, 9035, 9036, 9037, 9038, 9039, 9040 }, name = { ko = "일곱 현자", en = "The Seven" }, loot = { 11920, 11921, 11922, 11926, 11927, 11923, 11925, 11929 }, tip = { ko = "운명의 문지기에게 말을 걸면 하나씩 덤빕니다. 사이사이 마나를 채우세요. 끝나면 상자가 나옵니다.", en = "Talk to Doom'rel; they come one at a time. Drink between them. A chest appears at the end." } },
      { id = "s25", n = "", kind = "object", quest = true, optional = true, npc = {  }, name = { ko = "유령의 성배", en = "The Spectral Chalice" }, quests = { 4083 }, tip = { ko = "채광 230 이상이면 별루비를 바치고 검은무쇠 제련을 배웁니다.", en = "Mining 230+: offer star rubies to learn Smelt Dark Iron." } },
      { id = "s26", n = "15", kind = "task", npc = {  }, name = { ko = "훈련강당 화로", en = "Lyceum braziers" }, tip = { ko = "불꽃지기가 떨구는 횃불로 화로 둘에 불을 붙이면 철의 전당 문이 열립니다.", en = "Light both braziers with torches from the Flamekeepers to open the Iron Hall." } },
      { id = "s27", n = "16", kind = "boss", npc = { 9938 }, name = { ko = "마그무스", en = "Magmus" }, loot = { 11746, 11935, 22208, 22395, 22400 }, tip = { ko = "양옆 석상의 불길을 피하고 오른쪽 구석으로 끌어 잡으세요.", en = "Dodge the statues' fire; pull him to the right corner." } },
      { id = "s28", n = "17", kind = "boss", quest = true, npc = { 9019, 8929 }, name = { ko = "제왕 다그란 타우릿산", en = "Emperor Dagran Thaurissan" }, loot = { 11815, 11924, 11928, 11930, 11931, 11932, 11933, 11934, 22204, 22207, 11684, 12033 }, quests = { 4362, 4003 }, tip = { ko = "공주가 제왕을 치유하니 끊으세요. 공주 구출 퀘스트면 공주는 살려 두고 제왕만 잡습니다.", en = "The princess heals him; interrupt her. On the rescue quest keep her alive and kill only him." } },
      { id = "s29", n = "", kind = "object", quest = true, optional = true, npc = {  }, name = { ko = "핵 조각", en = "Core Fragment" }, quests = { 7848 }, tip = { ko = "작열하는 다리 끝, 화산 심장부 차원문 옆. 화산 심장부 입장 퀘스트.", en = "End of the bridge by the Molten Core portal; attunement quest." } },
      { id = "s30", n = "", kind = "rare", optional = true, npc = { 8923 }, name = { ko = "무적의 판저", en = "Panzor the Invincible" }, loot = { 11787, 11786, 11785, 22245 }, tip = { ko = "가끔 나타나는 희귀 골렘.", en = "Rare golem that does not always spawn." } },
