      { id = 4242, faction = "Alliance", level = 54, minLevel = 48, name = { ko = "실망", en = "Abandoned Hope" }, giver = { ko = "나쁜 소식을 맥스웰 치안대장에게.", en = "Give Marshal Maxwell the bad news." } },
