      { id = 4322, faction = "Alliance", level = 58, minLevel = 50, name = { ko = "탈옥!", en = "Jail Break!" }, giver = { ko = "윈저 치안대장의 장비를 되찾고 동료를 풀어주기.", en = "Help Windsor recover his gear and free his friends." } },
